export function trappingRainWater(heights: number[]): number {
let l=0,r=heights.length-1,left=0,right=0,total=0;while(l<=r){if(left<=right){left=Math.max(left,heights[l]);total+=left-heights[l++];}else{right=Math.max(right,heights[r]);total+=right-heights[r--];}}return total;
}
